def themeify(src):
    """Cambia colores neutros fijos por variables CSS (fallback = color original) para poder tener temas."""
    def lum(h):
        r,g,bb=[int(h[i:i+2],16) for i in (1,3,5)]
        return (0.299*r+0.587*g+0.114*bb)/255
    M={'#FBFAF8':'--card','#F7F6F3':'--bg','#EFEDE8':'--paper','#DCD6CC':'--line','#CFC8BB':'--line','#E4DFD6':'--line','#5A554E':'--gray',
       '#8b867e':'--gray2','#777':'--gray2','#555':'--gray','#888':'--gray2','#C0392B':'--red','#F5E4E0':'--red-tint','#96271B':'--red-strong'}
    src=re.sub(r'(background(?:-color)?:\s*)#1C1B19\b',r'\1var(--btn,#1C1B19)',src)
    src=re.sub(r'(background(?:-color)?:\s*)#fff\b',r'\1var(--wh,#fff)',src)
    for h,v in M.items():
        src=re.sub(r'(?<=[:\s,(])'+re.escape(h)+r'(?![0-9A-Za-z])','var('+v+','+h+')',src)
    src=re.sub(r'(?<=[:\s,(])#1C1B19(?![0-9A-Za-z])','var(--ink,#1C1B19)',src)
    def tint(m):
        h=m.group(2)
        if lum(h)>0.8: return m.group(1)+'color-mix(in srgb,'+h+' var(--tm,100%),var(--card,#FBFAF8))'
        return m.group(0)
    src=re.sub(r'(background(?:-color)?:\s*)(#[0-9A-Fa-f]{6})(?![0-9A-Za-z])',tint,src)
    src=src.replace('<polygon fill="#1C1B19"','<polygon fill="currentColor"')
    def rule(m):
        body=m.group(2)
        if re.search(r'(?<![-\w])color:\s*#fff',body) and 'background:var(--ink)' in body:
            body=body.replace('background:var(--ink)','background:var(--btn,var(--ink))')
        return m.group(1)+'{'+body+'}'
    src=re.sub(r'(--[a-z0-9-]+):var\(--[a-z0-9-]+,(#[0-9A-Fa-f]{3,6})\)',r'\1:\2',src)
    src=re.sub(r'([^{}]+)\{([^{}]*)\}',rule,src)
    def svgfix(m):
        t=m.group(0)
        for a in ('fill','stroke'):
            if (a+'="#1C1B19"') in t:
                t=t.replace(a+'="#1C1B19"','',1)
                if 'style="' in t: t=t.replace('style="','style="'+a+':var(--ink,#1C1B19);',1)
                else: t=t.replace('<','<',1)[:-1].rstrip('/')+' style="'+a+':var(--ink,#1C1B19)"'+('/>' if m.group(0).endswith('/>') else '>')
        return t
    src=re.sub(r'<[^<>]*(?:fill|stroke)="#1C1B19"[^<>]*>',svgfix,src)
    src=src.replace('<polygon fill="currentColor"','<polygon fill="currentColor"')
    return src


